<script lang="ts">
 let {label,field,value='',placeholder,rows=5,maxlength,required=false,disabled=false,error='',helpText='',element=$bindable(),onValueChange,onKeydown,onCompositionChange,onPaste,onDrop,onDragover}:{label:string;field:string;value?:string;placeholder?:string;rows?:number;maxlength?:number;required?:boolean;disabled?:boolean;error?:string;helpText?:string;element?:HTMLTextAreaElement;onValueChange:(value:string,event?:InputEvent)=>void;onKeydown?:(event:KeyboardEvent)=>void;onCompositionChange?:(composing:boolean)=>void;onPaste?:(event:ClipboardEvent)=>void;onDrop?:(event:DragEvent)=>void;onDragover?:(event:DragEvent)=>void}=$props();
